function ModalContent({title,exportReport,beginEdit}:{title:string;exportReport:()=>void;beginEdit:()=>void}) {
  if(title.includes('заказ')||title.includes('Заказ'))return <><p className=\"muted\">Последние заказы · Октябрь 2026</p><div className=\"detail-orders\">{[['1048','Анна Смирнова','12 450 ₽','Оплачен'],['1047','Михаил Петров','8 200 ₽','В обработке'],['1046','Елена Волкова','24 900 ₽','Оплачен']].filter(o=>title==='Все заказы'||title.includes(o[0])).map(o=><div key={o[0]}><strong>#{o[0]} · {o[1]}</strong><span>{o[2]} · {o[3]}</span><small>30 октября 2026 · Интернет-магазин</small></div>)}</div></>;
  if(title==='Источники данных')return <><p>Подключённые источники демо-пространства</p>{['Интернет-магазин','Веб-аналитика','Платёжная система'].map(s=><div className=\"source-row\" key={s}><Icon data={Database} size={19}/><strong>{s}</strong><span className=\"change\"><span className=\"status-dot\"/>Подключено</span></div>)}<p className=\"muted\">Данные демонстрационные и хранятся в приложении.</p></>;
  if(title==='Уведомления')return <><div className=\"notification-entry\"><span className=\"event-icon green\"><Icon data={Target} size={20}/></span><div><strong>Цель месяца выполнена на 83%</strong><p>До цели осталось 254 200 ₽. Продолжайте в том же темпе"'!</p><small className="muted">Сегодня, 12:42</small></div></div><p className="muted">Вы прочитали все уведомления.</p></>;
