export function App() {
  const [config,setConfig]=useState<Config>(readConfig);const [editing,setEditing]=useState(false);const [beforeEdit,setBeforeEdit]=useState<Config|null>(null);const [compact,setCompact]=useState(false);const [small,setSmall]=useState(window.innerWidth<760);const [period,setPeriod]=useState('month');const [catalogOpen,setCatalogOpen]=useState(false);const [query,setQuery]=useState('');const [modal,setModal]=useState<string|null>(null);const [toast,setToast]=useState('');const [activeTab,setActiveTab]=useState('overview');const [workspace,setWorkspace]=useState('Мой бизнес');const [savedAt,setSavedAt]=useState('Только что');
