w:'flat',size:'s','aria-label':'Меню профиля'}}/></>}</div></div>} renderContent={()=><div className=\"page-shell\"><header className=\"topbar\"><div className=\"breadcrumbs\"><span>Рабочее пространство</span><span className=\"breadcrumb-slash\">/</span><strong>Обзор</strong></div><div className=\"topbar-actions\"><span className=\"demo-badge\">Демо-данные</span><Button view=\"flat\" size=\"m\" aria-label=\"Найти виджет\" onClick={()=>setCatalogOpen(true)}><Icon data={Magnifier} size={18}/></Button><Button view=\"flat\" size=\"m\" aria-label=\"Уведомления\" className=\"notification-button\" onClick={()=>setModal('Уведомления')}><Icon data={Bell} size={18}/><i/></Button><span className=\"topbar-divider\"/><Button view=\"flat\" size=\"m\" aria-label=\"Профиль\" onClick={()=>setModal('Профиль')}><span className=\"avatar small-avatar\">АК</span></Button></div></header><main className=\"dashboard\"><div className=\"page-title-row\"><div><div className=\"eyebrow\">ВАША КАРТИНА ДНЯ</div><Text variant=\"display-1\" className=\"page-title\">Обзор бизнеса<span className=\"title-dot\">.</span></Text><p className=\"page-subtitle\">Все важные показатели. Один взгляд.</p></div><div className=\"title-actions\"><Button view=\"outlined\" size=\"l\" onClick={editing?finishEdit:beginEdit}><Icon data={editing?Check:Sliders} size={16}/>{editing?'Сохранить':'Настроить'}</Button><Button view=\"action\" size=\"l\" onClick={()=>setCatalogOpen(true)}><Icon data={Plus} size={17}/>Добавить виджет</Button></div></div><div className=\"dashboard-toolbar\"><div className=\"page-tabs\">{[{id:'overview',title:'Обзор'},{id:'sales',title:'Продажи'},{id:'audience',title:'Аудитория'}].map(tab=><Button key={tab.id} view=\"flat\" className={cn('page-tab',activeTab===tab.id&&'active-tab')} onClick={()=>setActiveTab(tab.id)}>{tab.title}{tab.id==='overview'&&<span className=\"tab-count\">{config.items.length}</span>}</Button>)}</div><div className=\"period-controls\"><Icon data={Calendar} size={15}/><Select 