function readConfig(): Config {try {const c=JSON.parse(localStorage.getItem('pulse-layout')||'null');if(c && Array.isArray(c.items) && Array.isArray(c.layout) && c.items.every((x: any)=>x.type==='pulse-widget' && catalog.some(c=>c.kind===x.data?.kind))) return c;} catch {} return initialConfig;}
