import {Chart, type ChartData} from '@gravity-ui/charts';
import {LayoutCellsLarge, ChartLine, ChartColumn, ChartDonut, Persons, ShoppingBag, Database, Gear, CircleQuestion, ArrowUpRight, ArrowDownRight, ArrowDownToLine, ArrowRight, ArrowRotateRight, Bell, Magnifier, Calendar, Plus, Sliders, Grip, Ellipsis, Check, Xmark, Copy, Target, ChevronDown, BookOpen} from '@gravity-ui/icons';
import './styles.css';

configure({lang: 'ru'});
type Config = DashKitProps['config'];
type Kind = 'revenue' | 'orders' | 'visitors' | 'conversion' | 'trend' | 'traffic' | 'recent' | 'goal' | 'activity';
const catalog: {kind: Kind; title: string; description: string; icon: typeof ChartLine; w: number; h: number}[] = [
  {kind:'revenue',title:'Выручка',description:'Доход и изменение за период',icon:ChartLine,w:9,h:6},
  {kind:'orders',title:'Заказы',description:'Количество оформленных заказов',icon:ShoppingBag,w:9,h:6},
  {kind:'visitors',title:'Посетители',description:'Уникальная аудитория сайта',icon:Persons,w:9,h:6},
  {kind:'conversion',title:'Конверсия',description:'Доля посетителей, сделавших заказ',icon:Target,w:9,h:6},
  {kind:'trend',title:'Динамика выручки',description:'Доход по дням и сравнение периодов',icon:ChartLine,w:24,h:14},
  {kind:'traffic',title:'Источники трафика',description:'Откуда приходят ваши посетители',icon:ChartDonut,w:12,h:14},
  {kind:'recent',title:'Последние заказы',description:'Новые заказы и их статусы',icon:ShoppingBag,w:17,h:12},
  {kind:'goal',title:'Цель месяца',description:'Прогресс на пути к вашей цели',icon:Target,w:9,h:12},
  {kind:'activity',title:'Активность',description:'Последние события вашего бизнеса',icon:ChartColumn,w:10,h:12},
];
const initialConfig: Config = {salt:'pulse',counter:10,aliases:{},connections:[],items:catalog.map((c,i)=>({id:String(i+1),type:'pulse-widget',namespace:'default',data:{kind:c.kind}})),layout:catalog.map((c,i)=>({i:String(i+1),w:c.w,h:c.h,x:i<4?i*9:i===5?24:i===7?17:i===8?26:0,y:i<4?0:i<6?6:20,minW:i<4?6:8,minH:i<4?6:10}))};
function readConfig(): Config {try {const c=JSON.parse(localStorage.getItem('pulse-layout')||'null');if(c && Array.isArray(c.items) && Array.isArray(c.layout) && c.items.every((x: any)=>x.type==='pulse-widget' && catalog.some(c=>c.kind===x.data?.kind))) return c;} catch {} return initialConfig;}
const DashboardContext=createContext({period:'month',editing:false,remove:(_id:string)=>{},duplicate:(_id:string)=>{},notify:(_message:string)=>{},details:(_title:string)=>{}});
const cn=(...names:(string|false|undefined)[])=>names.filter(Boolean).join(' ');
const money=(value:number)=>new Intl.NumberFormat('ru-RU').format(value);
const green='var(--g-color-base-brand)';
const sourceColors=[green,'var(--g-color-text-positive)','var(--g-color-line-positive)','var(--g-color-base-positive-light)'];
const trendValues=[38,48,44,43,59,53,48,62,51,70,63,60,72,66,85,79,63,74,66,88,80,105,98,87,94,115,108,117,104,126];
function Sparkline({seed=0,down=false}:{seed?:number;down?:boolean}) {const data:ChartData={chart:{margin:{top:3,bottom:3,left:0,right:0}},legend:{enabled:false},tooltip:{enabled:false},xAxis:{visible:false},yAxis:[{visible:false}],series:{data:[{type:'area',name:'Динамика',data:[8,12,10,15,11,20,17,22,18,26,24,30].map((y,x)=>({x,y:down?36-y:y+Math.sin(x+seed)*4})),color:down?'var(--g-color-text-warning)':green,opacity:.09,lineWidth:1.8}]}};return <div className=\"sparkline\"><Chart data={data}/></div>;}
function WidgetMenu({id}:{id:string}) {const ctx=useContext(DashboardContext);return <DropdownMenu size=\"s\" icon={<Icon data={Ellipsis} size={17}/>} defaultSwitcherProps={{view:'flat',size:'s','aria-label':'Действия с виджетом'}} items={[{text:'Дублировать',iconStart:<Icon data={Copy} size={14}/>,action:()=>ctx.duplicate(id)},{text:'Удалить виджет',theme:'danger',iconStart:<Icon data={Xmark} size={14}/>,action:()=>ctx.remove(id)}]}/>;}
function WidgetHeading({title,id,icon}:{title:string;id:string;icon?:typeof ChartLine}) {return <div className=\"widget-heading\"><div className=\"widget-title widget-drag-handle\">{icon&&<Icon data={icon} size={17}/>}<Text variant=\"subheader-1\">{title}</Text></div><span className=\"widget-grip widget-drag-handle\"><Icon data={Grip} size={15}/></span><WidgetMenu id={id}/></div>;}
function Widget({id,data}:PluginWidgetProps) {
  const ctx=useContext(DashboardContext); const kind=data.kind as Kind;
