    const index=['revenue','orders','visitors','conversion'].indexOf(kind);
    const stat=[{title:'Выручка',value:"'`${money(Math.round(1245800*multiplier))} ₽`,change:'"'12,8%',icon:ChartLine},{title:'Заказы',value:money(Math.round(1842*multiplier)),change:'8,2%',icon:ShoppingBag},{title:'Посетители',value:money(Math.round(48256*multiplier)),change:'16,4%',icon:Persons},{title:'Конверсия',value:'3,82%',change:'0,4%',icon:Target}][index];
    return <article className={cn('widget','stat-card',index===0&&'featured-stat')}><div className=\"stat-heading widget-drag-handle\"><span>{stat.title}</span><Icon data={stat.icon} size={18}/></div><div className=\"stat-value\"><Text variant=\"display-1\">{stat.value}</Text><Sparkline seed={index} down={index===3}/></div><div className=\"stat-footer\"><span className={cn('change',index===3&&'negative')}><Icon data={index===3?ArrowDownRight:ArrowUpRight} size={13}/>{stat.change}</span><span>к прошлому периоду</span></div>{ctx.editing&&<div className=\"stat-edit\"><WidgetMenu id={id}/></div>}</article>;
  }
  if(kind==='trend') {
    const categories=Array.from({length:30},(_,i)=>"'`${i+1} окт.`);
    const chart:ChartData={chart:{margin:{top:16,right:12,left:10,bottom:4}},legend:{enabled:false},xAxis:{type:'"'category',categories,grid:{enabled:false},lineVisible:false,ticks:{positions:[0,4,9,14,19,24,29]},labels:{style:{fontSize:'11px',fontColor:'var(--g-color-text-secondary)'}}},yAxis:[{min:0,max:150,lineVisible:false,ticks:{positions:[0,50,100,150]},labels:{style:{fontSize:'11px',fontColor:'var(--g-color-text-secondary)'}}}],series:{data:[{type:'line',name:'Прошлый период, тыс. ₽',data:trendValues.map((y,x)=>({x,y:(y*.62+Math.cos(x)*11)*multiplier})),color:'var(--g-color-line-positive)',dashStyle:'Dash',lineWidth:2},{type:'area',name:'Текущий период, тыс. ₽',data:trendValues.map((y,x)=>({x,y:y*multiplier})),color:green,opacity:.08,lineWidth:2.5} ]}};
    if(multiplier"'!==1) chart.yAxis=[{min:0,max:Math.ceil(150*multiplier/50)*50,lineVisible:false}];
    return <article className="widget trend-widget"><WidgetHeading title="Динамика выручки" id={id}/><div className="trend-info"><div><Text variant="header-1">{money(Math.round(1245800*multiplier))} ₽</Text><span className="change"><Icon data={ArrowUpRight} size={14}/>12,8%</span></div><span className="muted">тыс. ₽</span><div className="chart-key"><span><i/>Текущий период</span><span><i className="previous"/>Прошлый период</span></div></div><div className="revenue-chart"><Chart data={chart}/></div><div className="widget-bottom"><span><span className="status-dot"/>Выручка растёт быстрее прошлого периода</span><Icon data={ArrowUpRight} size={14}/></div></article>;
  }
  if(kind==='"'traffic') {
    const names=['Прямые переходы','Поисковые системы','Социальные сети','Другие источники'];const values=[42,32,18,8];
    const chart:ChartData={chart:{margin:{top:0,bottom:0,left:0,right:0}},legend:{enabled:false},series:{data:[{type:'pie',innerRadius:'78%',radius:'96%',borderWidth:3,dataLabels:{enabled:false},data:values.map((v,i)=>({name:names[i],value:v,color:sourceColors[i]}))}]}};
    return <article className=\"widget traffic-widget\"><WidgetHeading title=\"Источники трафика\" id={id}/><div className=\"donut-wrap\"><Chart data={chart}/><div className=\"donut-center\"><Text variant=\"header-1\">{money(Math.round(48256*multiplier))}</Text><span>посетителей</span></div></div><div className=\"traffic-legend\">{names.map((name,i)=><div key={name}><span><i style={{background:sourceColors[i]}}/>{name}</span><strong>{values[i]}%</strong></div>)}</div></article>;
